const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');
(async () => {
  const htmlPath = path.resolve('output/chart.html');
  const outPng = path.resolve('output/result.png');
  const html = fs.readFileSync(htmlPath, 'utf8');

  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1300, height: 900, deviceScaleFactor: 2 });

  // Intercept requests to serve local libs
  await page.setRequestInterception(true);
  page.on('request', req => {
    const url = req.url();
    if (url.startsWith('file://')) return req.continue();
    if (url.startsWith('http://') || url.startsWith('https://')) {
      // No external network assets expected
      return req.abort();
    }
    if (url.startsWith('app://')) return req.abort();

    // Handle absolute paths like /app/libs/...
    if (url.startsWith('file:///app/')) return req.continue();
    if (url.startsWith('file://app/')) return req.continue();

    // Chromium treats /app/... as http(s) sometimes when content is set; map it
    if (url.includes('/app/libs/')) {
      const local = url.substring(url.indexOf('/app/'));
      const abs = path.resolve(local);
      if (fs.existsSync(abs)) {
        const buf = fs.readFileSync(abs);
        const headers = {};
        if (abs.endsWith('.js')) headers['content-type'] = 'application/javascript';
        if (abs.endsWith('.css')) headers['content-type'] = 'text/css';
        return req.respond({ status: 200, body: buf, headers });
      }
    }
    return req.continue();
  });

  await page.setContent(html, { waitUntil: 'domcontentloaded' });

  // Wait for Chart.js to render
  await page.waitForFunction(() => {
    const c = document.getElementById('pcChart');
    return c && c.chart;
  }, { timeout: 10000 });

  // Wait a tick for layout
  await page.evaluate(() => new Promise(r => setTimeout(r, 50)));

  // Screenshot only main content
  const main = await page.$('#main-content');
  await main.screenshot({ path: outPng });
  await browser.close();
  console.log('wrote', outPng);
})();
